import React, { useState, useEffect } from 'react';
import { fetchVerseOfWeek, getScriptureDetails } from '../services/geminiService';
import { supabase } from '../services/supabaseClient';
import { Verse, Room, RoomMember, AppUser, WeeklyReading } from '../types';
import { Sparkles, Save, Loader2, Copy, Trash2, ShieldCheck, PenTool, ShieldOff, Edit2, Check, X, AlertTriangle, Archive, PlusCircle, RotateCcw, ChevronDown, ChevronRight } from 'lucide-react';

interface AdminPanelProps {
  room: Room;
  currentUser: AppUser;
  currentReading: WeeklyReading | null; // Kept for compat
  activeReadings?: WeeklyReading[];
  onRoomUpdate?: (room: Room) => void;
  onReadingUpdate: () => void;
}

const getErrorMessage = (error: unknown): string => {
  if (typeof error === 'string') return error;
  if (error instanceof Error) return error.message;
  if (typeof error === 'object' && error !== null) {
      // Check for common error properties
      if ('message' in error) return String((error as any).message);
      if ('error' in error) return String((error as any).error);
      return JSON.stringify(error);
  }
  return String(error);
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ room, currentUser, activeReadings = [], onRoomUpdate, onReadingUpdate }) => {
  const [activeTab, setActiveTab] = useState<'verse' | 'members' | 'settings'>('verse');

  // Verse Management State
  const [isPublishing, setIsPublishing] = useState(false);
  const [manualMode, setManualMode] = useState(true);

  // Manual Entry Form
  const [manualReference, setManualReference] = useState('');
  const [manualTheme, setManualTheme] = useState('');

  // Archive State
  const [archivedReadings, setArchivedReadings] = useState<WeeklyReading[]>([]);
  const [loadingArchived, setLoadingArchived] = useState(false);
  const [showArchived, setShowArchived] = useState(false);

  // Members State
  const [members, setMembers] = useState<RoomMember[]>([]);
  const [loadingMembers, setLoadingMembers] = useState(false);

  // Room Settings State
  const [isEditingName, setIsEditingName] = useState(false);
  const [editNameValue, setEditNameValue] = useState(room.name);
  const [savingName, setSavingName] = useState(false);

  // Status Message
  const [statusMsg, setStatusMsg] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    if (activeTab === 'members') fetchMembers();
    if (activeTab === 'verse' && showArchived) fetchArchivedReadings();
  }, [activeTab, showArchived, activeReadings]); // Refetch archive if active list changes

  // Clear messages after 5s
  useEffect(() => {
    if (statusMsg) {
        const timer = setTimeout(() => setStatusMsg(null), 5000);
        return () => clearTimeout(timer);
    }
  }, [statusMsg]);

  // --- Data Fetching ---

  const fetchMembers = async () => {
    setLoadingMembers(true);
    const { data, error } = await supabase
      .from('room_members')
      .select(`*, app_users (username, email)`)
      .eq('room_id', room.id);

    if (data) {
        const formatted = data.map((m: any) => ({
            ...m,
            app_users: Array.isArray(m.app_users) ? m.app_users[0] : m.app_users
        }));
        setMembers(formatted);
    }
    setLoadingMembers(false);
  };

  const fetchArchivedReadings = async () => {
    setLoadingArchived(true);

    // Fetch all readings
    const { data, error } = await supabase
        .from('weekly_readings')
        .select('*')
        .eq('room_id', room.id)
        .order('created_at', { ascending: false });

    if (data) {
        // 1. Identify IDs and References that are currently active
        const activeIds = new Set(activeReadings.map(r => r.id));
        const normalize = (s: string) => s.replace(/[\s\u00A0]+/g, '').toLowerCase();
        const activeRefs = new Set(activeReadings.map(r => normalize(r.reference)));

        // 2. Filter out active readings to get candidates for archive
        // We filter by ID (is this row active?) AND by Reference (is this scripture currently active elsewhere?)
        const inactiveCandidates = data.filter((r: WeeklyReading) => 
            !activeIds.has(r.id) && 
            !activeRefs.has(normalize(r.reference))
        );

        // 3. Deduplicate by Reference
        // Since we ordered by created_at DESC, the first occurrence of a reference is the most recent (and the one we want to keep)
        const uniqueMap = new Map<string, WeeklyReading>();

        inactiveCandidates.forEach((r: WeeklyReading) => {
            const key = normalize(r.reference);
            if (!uniqueMap.has(key)) {
                uniqueMap.set(key, r);
            }
        });

        // Convert map back to array
        setArchivedReadings(Array.from(uniqueMap.values()));
    }
    setLoadingArchived(false);
  };

  // --- Room Settings Actions ---

  const saveRoomName = async () => {
      if (!editNameValue.trim() || editNameValue === room.name) {
          setIsEditingName(false);
          return;
      }
      setSavingName(true);
      const { error } = await supabase.from('rooms').update({ name: editNameValue }).eq('id', room.id);
      setSavingName(false);

      if (!error) {
          if (onRoomUpdate) onRoomUpdate({ ...room, name: editNameValue });
          setIsEditingName(false);
          setStatusMsg({ type: 'success', text: 'Room name updated.' });
      } else {
          setStatusMsg({ type: 'error', text: 'Failed to update name.' });
      }
  };

  // --- Member Actions ---

  const toggleAdmin = async (memberId: string, currentRole: 'admin' | 'member', userId: string) => {
    if (userId === currentUser.id) {
        setStatusMsg({ type: 'error', text: "You cannot change your own role." });
        return;
    }

    const newRole = currentRole === 'admin' ? 'member' : 'admin';
    const { error } = await supabase
      .from('room_members')
      .update({ role: newRole })
      .eq('id', memberId);

    if (!error) fetchMembers();
    else setStatusMsg({ type: 'error', text: "Failed to update role." });
  };

  const removeMember = async (memberId: string, userId: string) => {
    if (userId === currentUser.id) {
        setStatusMsg({ type: 'error', text: "You cannot remove yourself." });
        return;
    }

    if (!window.confirm("Are you sure you want to remove this member?")) return;

    const { error } = await supabase.from('room_members').delete().eq('id', memberId);
    if (!error) fetchMembers();
    else setStatusMsg({ type: 'error', text: "Failed to remove member." });
  };

  // --- Verse Actions ---

  const handlePublish = async () => {
    setIsPublishing(true);
    setStatusMsg(null);

    try {
        let verseData: Partial<Verse>;

        if (manualMode) {
            if (!manualReference) {
                throw new Error("Reference is required.");
            }

            // Fetch NKJV text by default for storage
            const { text, fullReference } = await getScriptureDetails(manualReference, 'NKJV');

            verseData = {
                reference: fullReference,
                text: text, 
                version: 'NKJV', // Default stored version
                theme: manualTheme || null
            };
        } else {
            // AI Auto-Generate
            verseData = await fetchVerseOfWeek();
        }

        // Try to insert with is_active: true
        // Fallback handled if column missing
        try {
            const { error } = await supabase.from('weekly_readings').insert({
                room_id: room.id,
                reference: verseData.reference,
                text: verseData.text,
                version: verseData.version,
                theme: verseData.theme,
                is_active: true
            });
            if (error) throw error;
        } catch (err: unknown) {
            // If error is related to column missing, try legacy insert
            console.warn("Retrying publish without is_active flag", err);
            const { error: legacyError } = await supabase.from('weekly_readings').insert({
                room_id: room.id,
                reference: verseData.reference,
                text: verseData.text,
                version: verseData.version,
                theme: verseData.theme
            });
            if (legacyError) throw legacyError;
        }

        setStatusMsg({ type: 'success', text: "Scripture published successfully!" });
        setManualReference('');
        setManualTheme('');
        onReadingUpdate(); // Refresh app state
    } catch (err: unknown) {
        console.error(err);
        setStatusMsg({ type: 'error', text: "Failed to publish: " + getErrorMessage(err) });
    } finally {
        setIsPublishing(false);
    }
  };

  const deactivateReading = async (id: string) => {
      // Archive = set is_active to false
      try {
        const { error } = await supabase
            .from('weekly_readings')
            .update({ is_active: false })
            .eq('id', id);

        if (error) throw error;

        onReadingUpdate();
        setStatusMsg({ type: 'success', text: "Scripture archived." });
      } catch (err: unknown) {
         console.error("Archive error:", err);
         setStatusMsg({ type: 'error', text: "Archiving failed: " + getErrorMessage(err) });
      }
  };

  const reactivateReading = async (reading: WeeklyReading) => {
      // Reactivate = set is_active to true
      try {
          const { error } = await supabase
            .from('weekly_readings')
            .update({ is_active: true })
            .eq('id', reading.id);

          if (error) throw error;

          onReadingUpdate();
          fetchArchivedReadings(); // Refresh the archive list
          setStatusMsg({ type: 'success', text: "Scripture reactivated!" });
      } catch (err: any) {
          console.error(err);
          // If update fails (e.g. column missing), fallback to cloning (legacy behavior)
          const errorMsg = getErrorMessage(err);
          if (errorMsg.includes('column')) {
             try {
                 const { error: cloneError } = await supabase.from('weekly_readings').insert({
                     room_id: room.id,
                     reference: reading.reference,
                     text: reading.text,
                     version: reading.version,
                     theme: reading.theme
                     // Don't set is_active if column missing
                 });
                 if (cloneError) throw cloneError;
                 onReadingUpdate();
                 setStatusMsg({ type: 'success', text: "Scripture reposted (legacy mode)." });
             } catch (e: unknown) {
                 setStatusMsg({ type: 'error', text: "Error reactivating: " + getErrorMessage(e) });
             }
          } else {
             setStatusMsg({ type: 'error', text: "Error reactivating: " + errorMsg });
          }
      }
  };

  return (
    <div className="animate-fade-in pb-20 md:pb-0">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
           <div className="flex items-center gap-3">
             {isEditingName ? (
                 <div className="flex items-center gap-2">
                     <input 
                        className="text-2xl font-serif font-bold text-gray-900 border-b-2 border-bible-400 bg-transparent outline-none px-1"
                        value={editNameValue}
                        onChange={(e) => setEditNameValue(e.target.value)}
                        autoFocus
                     />
                     <button onClick={saveRoomName} disabled={savingName} className="p-1 bg-green-100 text-green-700 rounded hover:bg-green-200">
                         {savingName ? <Loader2 size={16} className="animate-spin"/> : <Check size={16} />}
                     </button>
                     <button onClick={() => { setIsEditingName(false); setEditNameValue(room.name); }} className="p-1 bg-red-100 text-red-700 rounded hover:bg-red-200">
                         <X size={16} />
                     </button>
                 </div>
             ) : (
                <div className="flex items-center gap-2 group">
                    <h2 className="text-3xl font-serif text-bible-900 font-bold">{room.name}</h2>
                    <button onClick={() => setIsEditingName(true)} className="text-gray-400 hover:text-bible-600 opacity-0 group-hover:opacity-100 transition-opacity">
                        <Edit2 size={18} />
                    </button>
                </div>
             )}
           </div>
           <p className="text-gray-500 mt-1 flex items-center gap-2">
             Room Code: <span className="font-mono bg-gray-100 px-2 py-0.5 rounded text-gray-800 font-medium select-all">{room.code}</span>
             <button className="text-bible-500 hover:text-bible-700" onClick={() => navigator.clipboard.writeText(room.code)} title="Copy Code">
                <Copy size={14} />
             </button>
           </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-gray-200 mb-8 overflow-x-auto">
        <TabButton active={activeTab === 'verse'} onClick={() => setActiveTab('verse')} label="Scripture Management" icon={<Sparkles size={18} />} />
        <TabButton active={activeTab === 'members'} onClick={() => setActiveTab('members')} label="Members" icon={<ShieldCheck size={18} />} />
        <TabButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} label="Settings" icon={<PenTool size={18} />} />
      </div>

      {statusMsg && (
        <div className={`mb-6 p-4 rounded-lg flex items-center gap-2 ${statusMsg.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
            {statusMsg.type === 'success' ? <Check size={18} /> : <AlertTriangle size={18} />}
            {statusMsg.text}
        </div>
      )}

      {/* --- VERSE MANAGEMENT TAB --- */}
      {activeTab === 'verse' && (
        <div className="space-y-10">

            {/* 1. Active Scriptures List */}
            <div className="bg-white p-6 rounded-xl border border-bible-200 shadow-sm">
                <h3 className="font-serif text-xl text-bible-900 mb-6 flex items-center gap-2">
                    <Check size={20} className="text-green-600" />
                    Active Scriptures
                </h3>

                {activeReadings.length > 0 ? (
                    <div className="space-y-4">
                        {activeReadings.map(reading => (
                            <div key={reading.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-bible-50 rounded-lg border border-bible-100">
                                <div>
                                    <h4 className="font-bold text-bible-900">{reading.reference}</h4>
                                    <div className="text-sm text-gray-500 flex items-center gap-2 mt-1">
                                        <span>{reading.theme || 'No theme'}</span>
                                        <span>•</span>
                                        <span>{new Date(reading.created_at).toLocaleDateString()}</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3 mt-4 sm:mt-0">
                                    <button 
                                        onClick={() => deactivateReading(reading.id)}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-white border border-gray-300 text-gray-600 rounded-lg hover:bg-gray-50 hover:text-red-600 transition-colors text-sm font-medium shadow-sm"
                                    >
                                        <Archive size={16} />
                                        Archive
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-8 text-gray-400 bg-gray-50 rounded-lg border border-dashed border-gray-200">
                        No active scriptures currently. Publish one below.
                    </div>
                )}
            </div>

            {/* 2. Publish New */}
            <div className="bg-white p-6 rounded-xl border border-bible-200 shadow-sm">
                <h3 className="font-serif text-xl text-bible-900 mb-6 flex items-center gap-2">
                    <PlusCircle size={20} className="text-bible-600" />
                    Publish New Scripture
                </h3>

                {/* Toggle Mode */}
                <div className="flex gap-4 mb-6">
                    <button 
                        onClick={() => setManualMode(true)}
                        className={`flex-1 py-3 rounded-lg border font-medium transition-all ${manualMode ? 'bg-bible-50 border-bible-300 text-bible-800' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'}`}
                    >
                        Manual Entry
                    </button>
                    <button 
                        onClick={() => setManualMode(false)}
                        className={`flex-1 py-3 rounded-lg border font-medium transition-all ${!manualMode ? 'bg-bible-50 border-bible-300 text-bible-800' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'}`}
                    >
                        AI Suggestion
                    </button>
                </div>

                {manualMode ? (
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-1">Theme (Optional)</label>
                            <input
                                type="text"
                                value={manualTheme}
                                onChange={(e) => setManualTheme(e.target.value)}
                                placeholder="e.g. Leadership, Faith, Patience"
                                className="w-full px-4 py-3 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-300 outline-none text-gray-900 placeholder:text-gray-400"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-1">Scripture Reference</label>
                            <input
                                type="text"
                                value={manualReference}
                                onChange={(e) => setManualReference(e.target.value)}
                                placeholder="e.g. Psalms 23:1-4"
                                className="w-full px-4 py-3 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-300 outline-none text-gray-900 placeholder:text-gray-400"
                            />
                            <p className="text-xs text-gray-500 mt-1">
                                We'll automatically fetch the text for the NKJV version. Users can switch versions in the Read tab.
                            </p>
                        </div>
                    </div>
                ) : (
                    <div className="bg-gradient-to-br from-bible-50 to-white p-6 rounded-lg border border-bible-100 text-center">
                        <Sparkles className="mx-auto text-bible-400 mb-3" size={32} />
                        <p className="text-bible-800 font-medium mb-2">Let AI find the perfect verse</p>
                        <p className="text-sm text-gray-500">
                            We'll analyze a topic suitable for a professional team setting and generate a relevant scripture.
                        </p>
                    </div>
                )}

                <div className="mt-8 flex justify-end">
                    <button
                        onClick={handlePublish}
                        disabled={isPublishing || (manualMode && !manualReference)}
                        className="bg-bible-700 hover:bg-bible-800 text-white px-8 py-3 rounded-lg flex items-center gap-2 font-medium disabled:opacity-50 transition-all shadow-md hover:shadow-lg active:scale-95"
                    >
                        {isPublishing ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />}
                        {isPublishing ? 'Publishing...' : 'Publish Scripture'}
                    </button>
                </div>
            </div>

            {/* 3. Archived List */}
            <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                <button 
                    onClick={() => setShowArchived(!showArchived)}
                    className="w-full flex items-center justify-between p-6 bg-gray-50 hover:bg-gray-100 transition-colors"
                >
                    <div className="flex items-center gap-2 font-serif text-lg text-gray-700">
                        <Archive size={20} />
                        Archived Scriptures
                    </div>
                    {showArchived ? <ChevronDown size={20} className="text-gray-400" /> : <ChevronRight size={20} className="text-gray-400" />}
                </button>

                {showArchived && (
                    <div className="p-6 border-t border-gray-200">
                        {loadingArchived ? (
                            <div className="flex justify-center py-4"><Loader2 className="animate-spin text-gray-400" /></div>
                        ) : archivedReadings.length === 0 ? (
                            <p className="text-center text-gray-400 italic">No archived scriptures found.</p>
                        ) : (
                            <div className="divide-y divide-gray-100">
                                {archivedReadings.map(archived => (
                                    <div key={archived.id} className="py-4 flex items-center justify-between group">
                                        <div>
                                            <p className="font-semibold text-gray-800">{archived.reference}</p>
                                            <p className="text-xs text-gray-400">
                                                {new Date(archived.created_at).toLocaleDateString()}
                                            </p>
                                        </div>
                                        <button 
                                            onClick={() => reactivateReading(archived)}
                                            className="text-bible-600 hover:text-bible-800 text-sm font-medium flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <RotateCcw size={14} />
                                            Reactivate
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
      )}

      {/* --- MEMBERS TAB --- */}
      {activeTab === 'members' && (
        <div className="bg-white rounded-xl shadow-sm border border-bible-200 overflow-hidden">
           <div className="p-6 border-b border-gray-100">
               <h3 className="font-serif text-xl text-bible-900">Room Members</h3>
               <p className="text-sm text-gray-500 mt-1">Manage access and roles</p>
           </div>

           {loadingMembers ? (
               <div className="p-10 flex justify-center"><Loader2 className="animate-spin text-bible-400" /></div>
           ) : (
               <table className="w-full text-left">
                   <thead className="bg-gray-50 text-gray-500 text-xs uppercase font-semibold">
                       <tr>
                           <th className="px-6 py-4">User</th>
                           <th className="px-6 py-4">Role</th>
                           <th className="px-6 py-4 text-right">Actions</th>
                       </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-100">
                       {members.map(member => (
                           <tr key={member.id} className="hover:bg-gray-50/50">
                               <td className="px-6 py-4">
                                   <div className="font-medium text-gray-900">{member.app_users?.username || 'Unknown'}</div>
                                   <div className="text-sm text-gray-500">{member.app_users?.email}</div>
                               </td>
                               <td className="px-6 py-4">
                                   <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${member.role === 'admin' ? 'bg-purple-100 text-purple-800' : 'bg-gray-100 text-gray-800'}`}>
                                       {member.role}
                                   </span>
                               </td>
                               <td className="px-6 py-4 text-right">
                                   <div className="flex justify-end gap-2">
                                       {member.user_id !== currentUser.id && (
                                           <>
                                            <button 
                                                onClick={() => toggleAdmin(member.id, member.role, member.user_id)}
                                                className="p-2 text-gray-400 hover:text-bible-600 hover:bg-bible-50 rounded transition-colors"
                                                title={member.role === 'admin' ? "Revoke Admin" : "Make Admin"}
                                            >
                                                {member.role === 'admin' ? <ShieldOff size={18} /> : <ShieldCheck size={18} />}
                                            </button>
                                            <button 
                                                onClick={() => removeMember(member.id, member.user_id)}
                                                className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                                                title="Remove User"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                           </>
                                       )}
                                   </div>
                               </td>
                           </tr>
                       ))}
                   </tbody>
               </table>
           )}
        </div>
      )}

      {/* --- SETTINGS TAB --- */}
      {activeTab === 'settings' && (
          <div className="bg-white p-8 rounded-xl border border-bible-200 shadow-sm text-center">
              <div className="inline-block p-4 bg-red-50 text-red-500 rounded-full mb-4">
                  <AlertTriangle size={32} />
              </div>
              <h3 className="text-xl font-serif text-gray-900 mb-2">Danger Zone</h3>
              <p className="text-gray-500 mb-6 max-w-md mx-auto">
                  Deleting a room is permanent and cannot be undone. All reflections and history will be lost.
              </p>
              <button disabled className="bg-gray-100 text-gray-400 px-6 py-2 rounded-lg cursor-not-allowed font-medium">
                  Delete Room (Coming Soon)
              </button>
          </div>
      )}

    </div>
  );
};

const TabButton = ({ active, onClick, label, icon }: { active: boolean, onClick: () => void, label: string, icon: React.ReactNode }) => (
    <button
        onClick={onClick}
        className={`flex items-center gap-2 px-6 py-4 border-b-2 font-medium text-sm transition-colors whitespace-nowrap ${
            active 
            ? 'border-bible-600 text-bible-800' 
            : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
        }`}
    >
        {icon}
        {label}
    </button>
);

