import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
});

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  build: {
    // Increase the warning limit to 1600kb to handle large libraries like Recharts/GenAI
    chunkSizeWarningLimit: 1600,
    rollupOptions: {
      output: {
        manualChunks: {
          // Split vendor code into separate chunks for better caching and performance
          vendor: ['react', 'react-dom', 'recharts', '@supabase/supabase-js', 'lucide-react', '@google/genai'],
        },
      },
    },
  },
});

import React, { useState, useEffect } from 'react';
import { fetchVerseOfWeek, getScriptureDetails } from '../services/geminiService';
import { supabase } from '../services/supabaseClient';
import { Verse, Room, RoomMember, AppUser, WeeklyReading } from '../types';
import { Sparkles, Save, Loader2, Copy, Trash2, ShieldCheck, PenTool, ShieldOff, Edit2, Check, X, AlertTriangle, Archive, PlusCircle, RotateCcw, ChevronDown, ChevronRight } from 'lucide-react';

interface AdminPanelProps {
  room: Room;
  currentUser: AppUser;
  currentReading: WeeklyReading | null; // Kept for compat
  activeReadings?: WeeklyReading[];
  onRoomUpdate?: (room: Room) => void;
  onReadingUpdate: () => void;
}

const getErrorMessage = (error: unknown): string => {
  if (typeof error === 'string') return error;
  if (error instanceof Error) return error.message;
  if (typeof error === 'object' && error !== null) {
      // Check for common error properties
      if ('message' in error) return String((error as any).message);
      if ('error' in error) return String((error as any).error);
      return JSON.stringify(error);
  }
  return String(error);
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ room, currentUser, activeReadings = [], onRoomUpdate, onReadingUpdate }) => {
  const [activeTab, setActiveTab] = useState<'verse' | 'members' | 'settings'>('verse');

  // Verse Management State
  const [isPublishing, setIsPublishing] = useState(false);
  const [manualMode, setManualMode] = useState(true);

  // Manual Entry Form
  const [manualReference, setManualReference] = useState('');
  const [manualTheme, setManualTheme] = useState('');

  // Archive State
  const [archivedReadings, setArchivedReadings] = useState<WeeklyReading[]>([]);
  const [loadingArchived, setLoadingArchived] = useState(false);
  const [showArchived, setShowArchived] = useState(false);

  // Members State
  const [members, setMembers] = useState<RoomMember[]>([]);
  const [loadingMembers, setLoadingMembers] = useState(false);

  // Room Settings State
  const [isEditingName, setIsEditingName] = useState(false);
  const [editNameValue, setEditNameValue] = useState(room.name);
  const [savingName, setSavingName] = useState(false);

  // Status Message
  const [statusMsg, setStatusMsg] = useState<{type: 'success' | 'error', text: string} | null>(null);

  useEffect(() => {
    if (activeTab === 'members') fetchMembers();
    if (activeTab === 'verse' && showArchived) fetchArchivedReadings();
  }, [activeTab, showArchived, activeReadings]); // Refetch archive if active list changes

  // Clear messages after 5s
  useEffect(() => {
    if (statusMsg) {
        const timer = setTimeout(() => setStatusMsg(null), 5000);
        return () => clearTimeout(timer);
    }
  }, [statusMsg]);

  // --- Data Fetching ---

  const fetchMembers = async () => {
    setLoadingMembers(true);
    const { data, error } = await supabase
      .from('room_members')
      .select(`*, app_users (username, email)`)
      .eq('room_id', room.id);

    if (data) {
        const formatted = data.map((m: any) => ({
            ...m,
            app_users: Array.isArray(m.app_users) ? m.app_users[0] : m.app_users
        }));
        setMembers(formatted);
    }
    setLoadingMembers(false);
  };

  const fetchArchivedReadings = async () => {
    setLoadingArchived(true);

    // Fetch all readings
    const { data, error } = await supabase
        .from('weekly_readings')
        .select('*')
        .eq('room_id', room.id)
        .order('created_at', { ascending: false });

    if (data) {
        // 1. Identify IDs and References that are currently active
        const activeIds = new Set(activeReadings.map(r => r.id));
        const normalize = (s: string) => s.replace(/[\s\u00A0]+/g, '').toLowerCase();
        const activeRefs = new Set(activeReadings.map(r => normalize(r.reference)));

        // 2. Filter out active readings to get candidates for archive
        // We filter by ID (is this row active?) AND by Reference (is this scripture currently active elsewhere?)
        const inactiveCandidates = data.filter((r: WeeklyReading) => 
            !activeIds.has(r.id) && 
            !activeRefs.has(normalize(r.reference))
        );

        // 3. Deduplicate by Reference
        // Since we ordered by created_at DESC, the first occurrence of a reference is the most recent (and the one we want to keep)
        const uniqueMap = new Map<string, WeeklyReading>();

        inactiveCandidates.forEach((r: WeeklyReading) => {
            const key = normalize(r.reference);
            if (!uniqueMap.has(key)) {
                uniqueMap.set(key, r);
            }
        });

        // Convert map back to array
        setArchivedReadings(Array.from(uniqueMap.values()));
    }
    setLoadingArchived(false);
  };

  // --- Room Settings Actions ---

  const saveRoomName = async () => {
      if (!editNameValue.trim() || editNameValue === room.name) {
          setIsEditingName(false);
          return;
      }
      setSavingName(true);
      const { error } = await supabase.from('rooms').update({ name: editNameValue }).eq('id', room.id);
      setSavingName(false);

      if (!error) {
          if (onRoomUpdate) onRoomUpdate({ ...room, name: editNameValue });
          setIsEditingName(false);
          setStatusMsg({ type: 'success', text: 'Room name updated.' });
      } else {
          setStatusMsg({ type: 'error', text: 'Failed to update name.' });
      }
  };

  // --- Member Actions ---

  const toggleAdmin = async (memberId: string, currentRole: 'admin' | 'member', userId: string) => {
    if (userId === currentUser.id) {
        setStatusMsg({ type: 'error', text: "You cannot change your own role." });
        return;
    }

    const newRole = currentRole === 'admin' ? 'member' : 'admin';
    const { error } = await supabase
      .from('room_members')
      .update({ role: newRole })
      .eq('id', memberId);

    if (!error) fetchMembers();
    else setStatusMsg({ type: 'error', text: "Failed to update role." });
  };

  const removeMember = async (memberId: string, userId: string) => {
    if (userId === currentUser.id) {
        setStatusMsg({ type: 'error', text: "You cannot remove yourself." });
        return;
    }

    if (!window.confirm("Are you sure you want to remove this member?")) return;

    const { error } = await supabase.from('room_members').delete().eq('id', memberId);
    if (!error) fetchMembers();
    else setStatusMsg({ type: 'error', text: "Failed to remove member." });
  };

  // --- Verse Actions ---

  const handlePublish = async () => {
    setIsPublishing(true);
    setStatusMsg(null);

    try {
        let verseData: Partial<Verse>;

        if (manualMode) {
            if (!manualReference) {
                throw new Error("Reference is required.");
            }

            // Fetch NKJV text by default for storage
            const { text, fullReference } = await getScriptureDetails(manualReference, 'NKJV');

            verseData = {
                reference: fullReference,
                text: text, 
                version: 'NKJV', // Default stored version
                theme: manualTheme || undefined // Changed from null to undefined to match strict types
            };
        } else {
            // AI Auto-Generate
            verseData = await fetchVerseOfWeek();
        }

        // Try to insert with is_active: true
        // Fallback handled if column missing
        try {
            const { error } = await supabase.from('weekly_readings').insert({
                room_id: room.id,
                reference: verseData.reference,
                text: verseData.text,
                version: verseData.version,
                theme: verseData.theme,
                is_active: true
            });
            if (error) throw error;
        } catch (err: unknown) {
            // If error is related to column missing, try legacy insert
            console.warn("Retrying publish without is_active flag", err);
            const { error: legacyError } = await supabase.from('weekly_readings').insert({
                room_id: room.id,
                reference: verseData.reference,
                text: verseData.text,
                version: verseData.version,
                theme: verseData.theme
            });
            if (legacyError) throw legacyError;
        }

        setStatusMsg({ type: 'success', text: "Scripture published successfully!" });
        setManualReference('');
        setManualTheme('');
        onReadingUpdate(); // Refresh app state
    } catch (err: unknown) {
        console.error(err);
        setStatusMsg({ type: 'error', text: "Failed to publish: " + getErrorMessage(err) });
    } finally {
        setIsPublishing(false);
    }
  };

  const deactivateReading = async (id: string) => {
      // Archive = set is_active to false
      try {
        const { error } = await supabase
            .from('weekly_readings')
            .update({ is_active: false })
            .eq('id', id);

        if (error) throw error;

        onReadingUpdate();
        setStatusMsg({ type: 'success', text: "Scripture archived." });
      } catch (err: unknown) {
         console.error("Archive error:", err);
         setStatusMsg({ type: 'error', text: "Archiving failed: " + getErrorMessage(err) });
      }
  };

  const reactivateReading = async (reading: WeeklyReading) => {
      // Reactivate = set is_active to true
      try {
          const { error } = await supabase
            .from('weekly_readings')
            .update({ is_active: true })
            .eq('id', reading.id);

          if (error) throw error;

          onReadingUpdate();
          fetchArchivedReadings(); // Refresh the archive list
          setStatusMsg({ type: 'success', text: "Scripture reactivated!" });
      } catch (err: any) {
          console.error(err);
          // If update fails (e.g. column missing), fallback to cloning (legacy behavior)
          const errorMsg = getErrorMessage(err);
          if (errorMsg.includes('column')) {
             try {
                 const { error: cloneError } = await supabase.from('weekly_readings').insert({
                     room_id: room.id,
                     reference: reading.reference,
                     text: reading.text,
                     version: reading.version,
                     theme: reading.theme
                     // Don't set is_active if column missing
                 });
                 if (cloneError) throw cloneError;
                 onReadingUpdate();
                 setStatusMsg({ type: 'success', text: "Scripture reposted (legacy mode)." });
             } catch (e: unknown) {
                 setStatusMsg({ type: 'error', text: "Error reactivating: " + getErrorMessage(e) });
             }
          } else {
             setStatusMsg({ type: 'error', text: "Error reactivating: " + errorMsg });
          }
      }
  };

  return (
    <div className="animate-fade-in pb-20 md:pb-0">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
           <div className="flex items-center gap-3">
             {isEditingName ? (
                 <div className="flex items-center gap-2">
                     <input 
                        className="text-2xl font-serif font-bold text-gray-900 border-b-2 border-bible-400 bg-transparent outline-none px-1"
                        value={editNameValue}
                        onChange={(e) => setEditNameValue(e.target.value)}
                        autoFocus
                     />
                     <button onClick={saveRoomName} disabled={savingName} className="p-1 bg-green-100 text-green-700 rounded hover:bg-green-200">
                         {savingName ? <Loader2 size={16} className="animate-spin"/> : <Check size={16} />}
                     </button>
                     <button onClick={() => { setIsEditingName(false); setEditNameValue(room.name); }} className="p-1 bg-red-100 text-red-700 rounded hover:bg-red-200">
                         <X size={16} />
                     </button>
                 </div>
             ) : (
                <div className="flex items-center gap-2 group">
                    <h2 className="text-3xl font-serif text-bible-900 font-bold">{room.name}</h2>
                    <button onClick={() => setIsEditingName(true)} className="text-gray-400 hover:text-bible-600 opacity-0 group-hover:opacity-100 transition-opacity">
                        <Edit2 size={18} />
                    </button>
                </div>
             )}
           </div>
           <p className="text-gray-500 mt-1 flex items-center gap-2">
             Room Code: <span className="font-mono bg-gray-100 px-2 py-0.5 rounded text-gray-800 font-medium select-all">{room.code}</span>
             <button className="text-bible-500 hover:text-bible-700" onClick={() => navigator.clipboard.writeText(room.code)} title="Copy Code">
                <Copy size={14} />
             </button>
           </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-gray-200 mb-8 overflow-x-auto">
        <TabButton active={activeTab === 'verse'} onClick={() => setActiveTab('verse')} label="Scripture Management" icon={<Sparkles size={18} />} />
        <TabButton active={activeTab === 'members'} onClick={() => setActiveTab('members')} label="Members" icon={<ShieldCheck size={18} />} />
        <TabButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} label="Settings" icon={<PenTool size={18} />} />
      </div>

      {statusMsg && (
        <div className={`mb-6 p-4 rounded-lg flex items-center gap-2 ${statusMsg.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
            {statusMsg.type === 'success' ? <Check size={18} /> : <AlertTriangle size={18} />}
            {statusMsg.text}
        </div>
      )}

      {/* --- VERSE MANAGEMENT TAB --- */}
      {activeTab === 'verse' && (
        <div className="space-y-10">

            {/* 1. Active Scriptures List */}
            <div className="bg-white p-6 rounded-xl border border-bible-200 shadow-sm">
                <h3 className="font-serif text-xl text-bible-900 mb-6 flex items-center gap-2">
                    <Check size={20} className="text-green-600" />
                    Active Scriptures
                </h3>

                {activeReadings.length > 0 ? (
                    <div className="space-y-4">
                        {activeReadings.map(reading => (
                            <div key={reading.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-bible-50 rounded-lg border border-bible-100">
                                <div>
                                    <h4 className="font-bold text-bible-900">{reading.reference}</h4>
                                    <div className="text-sm text-gray-500 flex items-center gap-2 mt-1">
                                        <span>{reading.theme || 'No theme'}</span>
                                        <span>•</span>
                                        <span>{new Date(reading.created_at).toLocaleDateString()}</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3 mt-4 sm:mt-0">
                                    <button 
                                        onClick={() => deactivateReading(reading.id)}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-white border border-gray-300 text-gray-600 rounded-lg hover:bg-gray-50 hover:text-red-600 transition-colors text-sm font-medium shadow-sm"
                                    >
                                        <Archive size={16} />
                                        Archive
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-8 text-gray-400 bg-gray-50 rounded-lg border border-dashed border-gray-200">
                        No active scriptures currently. Publish one below.
                    </div>
                )}
            </div>

            {/* 2. Publish New */}
            <div className="bg-white p-6 rounded-xl border border-bible-200 shadow-sm">
                <h3 className="font-serif text-xl text-bible-900 mb-6 flex items-center gap-2">
                    <PlusCircle size={20} className="text-bible-600" />
                    Publish New Scripture
                </h3>

                {/* Toggle Mode */}
                <div className="flex gap-4 mb-6">
                    <button 
                        onClick={() => setManualMode(true)}
                        className={`flex-1 py-3 rounded-lg border font-medium transition-all ${manualMode ? 'bg-bible-50 border-bible-300 text-bible-800' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'}`}
                    >
                        Manual Entry
                    </button>
                    <button 
                        onClick={() => setManualMode(false)}
                        className={`flex-1 py-3 rounded-lg border font-medium transition-all ${!manualMode ? 'bg-bible-50 border-bible-300 text-bible-800' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'}`}
                    >
                        AI Suggestion
                    </button>
                </div>

                {manualMode ? (
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-1">Theme (Optional)</label>
                            <input
                                type="text"
                                value={manualTheme}
                                onChange={(e) => setManualTheme(e.target.value)}
                                placeholder="e.g. Leadership, Faith, Patience"
                                className="w-full px-4 py-3 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-300 outline-none text-gray-900 placeholder:text-gray-400"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-1">Scripture Reference</label>
                            <input
                                type="text"
                                value={manualReference}
                                onChange={(e) => setManualReference(e.target.value)}
                                placeholder="e.g. Psalms 23:1-4"
                                className="w-full px-4 py-3 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-300 outline-none text-gray-900 placeholder:text-gray-400"
                            />
                            <p className="text-xs text-gray-500 mt-1">
                                We'll automatically fetch the text for the NKJV version. Users can switch versions in the Read tab.
                            </p>
                        </div>
                    </div>
                ) : (
                    <div className="bg-gradient-to-br from-bible-50 to-white p-6 rounded-lg border border-bible-100 text-center">
                        <Sparkles className="mx-auto text-bible-400 mb-3" size={32} />
                        <p className="text-bible-800 font-medium mb-2">Let AI find the perfect verse</p>
                        <p className="text-sm text-gray-500">
                            We'll analyze a topic suitable for a professional team setting and generate a relevant scripture.
                        </p>
                    </div>
                )}

                <div className="mt-8 flex justify-end">
                    <button
                        onClick={handlePublish}
                        disabled={isPublishing || (manualMode && !manualReference)}
                        className="bg-bible-700 hover:bg-bible-800 text-white px-8 py-3 rounded-lg flex items-center gap-2 font-medium disabled:opacity-50 transition-all shadow-md hover:shadow-lg active:scale-95"
                    >
                        {isPublishing ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />}
                        {isPublishing ? 'Publishing...' : 'Publish Scripture'}
                    </button>
                </div>
            </div>

            {/* 3. Archived List */}
            <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                <button 
                    onClick={() => setShowArchived(!showArchived)}
                    className="w-full flex items-center justify-between p-6 bg-gray-50 hover:bg-gray-100 transition-colors"
                >
                    <div className="flex items-center gap-2 font-serif text-lg text-gray-700">
                        <Archive size={20} />
                        Archived Scriptures
                    </div>
                    {showArchived ? <ChevronDown size={20} className="text-gray-400" /> : <ChevronRight size={20} className="text-gray-400" />}
                </button>

                {showArchived && (
                    <div className="p-6 border-t border-gray-200">
                        {loadingArchived ? (
                            <div className="flex justify-center py-4"><Loader2 className="animate-spin text-gray-400" /></div>
                        ) : archivedReadings.length === 0 ? (
                            <p className="text-center text-gray-400 italic">No archived scriptures found.</p>
                        ) : (
                            <div className="divide-y divide-gray-100">
                                {archivedReadings.map(archived => (
                                    <div key={archived.id} className="py-4 flex items-center justify-between group">
                                        <div>
                                            <p className="font-semibold text-gray-800">{archived.reference}</p>
                                            <p className="text-xs text-gray-400">
                                                {new Date(archived.created_at).toLocaleDateString()}
                                            </p>
                                        </div>
                                        <button 
                                            onClick={() => reactivateReading(archived)}
                                            className="text-bible-600 hover:text-bible-800 text-sm font-medium flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <RotateCcw size={14} />
                                            Reactivate
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
      )}

      {/* --- MEMBERS TAB --- */}
      {activeTab === 'members' && (
        <div className="bg-white rounded-xl shadow-sm border border-bible-200 overflow-hidden">
           <div className="p-6 border-b border-gray-100">
               <h3 className="font-serif text-xl text-bible-900">Room Members</h3>
               <p className="text-sm text-gray-500 mt-1">Manage access and roles</p>
           </div>

           {loadingMembers ? (
               <div className="p-10 flex justify-center"><Loader2 className="animate-spin text-bible-400" /></div>
           ) : (
               <table className="w-full text-left">
                   <thead className="bg-gray-50 text-gray-500 text-xs uppercase font-semibold">
                       <tr>
                           <th className="px-6 py-4">User</th>
                           <th className="px-6 py-4">Role</th>
                           <th className="px-6 py-4 text-right">Actions</th>
                       </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-100">
                       {members.map(member => (
                           <tr key={member.id} className="hover:bg-gray-50/50">
                               <td className="px-6 py-4">
                                   <div className="font-medium text-gray-900">{member.app_users?.username || 'Unknown'}</div>
                                   <div className="text-sm text-gray-500">{member.app_users?.email}</div>
                               </td>
                               <td className="px-6 py-4">
                                   <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${member.role === 'admin' ? 'bg-purple-100 text-purple-800' : 'bg-gray-100 text-gray-800'}`}>
                                       {member.role}
                                   </span>
                               </td>
                               <td className="px-6 py-4 text-right">
                                   <div className="flex justify-end gap-2">
                                       {member.user_id !== currentUser.id && (
                                           <>
                                            <button 
                                                onClick={() => toggleAdmin(member.id, member.role, member.user_id)}
                                                className="p-2 text-gray-400 hover:text-bible-600 hover:bg-bible-50 rounded transition-colors"
                                                title={member.role === 'admin' ? "Revoke Admin" : "Make Admin"}
                                            >
                                                {member.role === 'admin' ? <ShieldOff size={18} /> : <ShieldCheck size={18} />}
                                            </button>
                                            <button 
                                                onClick={() => removeMember(member.id, member.user_id)}
                                                className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                                                title="Remove User"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                           </>
                                       )}
                                   </div>
                               </td>
                           </tr>
                       ))}
                   </tbody>
               </table>
           )}
        </div>
      )}

      {/* --- SETTINGS TAB --- */}
      {activeTab === 'settings' && (
          <div className="bg-white p-8 rounded-xl border border-bible-200 shadow-sm text-center">
              <div className="inline-block p-4 bg-red-50 text-red-500 rounded-full mb-4">
                  <AlertTriangle size={32} />
              </div>
              <h3 className="text-xl font-serif text-gray-900 mb-2">Danger Zone</h3>
              <p className="text-gray-500 mb-6 max-w-md mx-auto">
                  Deleting a room is permanent and cannot be undone. All reflections and history will be lost.
              </p>
              <button disabled className="bg-gray-100 text-gray-400 px-6 py-2 rounded-lg cursor-not-allowed font-medium">
                  Delete Room (Coming Soon)
              </button>
          </div>
      )}

    </div>
  );
};

const TabButton = ({ active, onClick, label, icon }: { active: boolean, onClick: () => void, label: string, icon: React.ReactNode }) => (
    <button
        onClick={onClick}
        className={`flex items-center gap-2 px-6 py-4 border-b-2 font-medium text-sm transition-colors whitespace-nowrap ${
            active 
            ? 'border-bible-600 text-bible-800' 
            : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
        }`}
    >
        {icon}
        {label}
    </button>
);

import React, { useState, useEffect } from 'react';
import { WeeklyReading, Reflection, AppView, AppUser, Room } from './types';
import { supabase } from './services/supabaseClient';
import { VerseHero } from './components/VerseHero';
import { ReflectionInput } from './components/ReflectionInput';
import { Dashboard } from './components/Dashboard';
import { Auth } from './components/Auth';
import { AdminPanel } from './components/AdminPanel';
import { ReflectionsList } from './components/ReflectionsList';
import { History } from './components/History';
import { Lobby } from './components/Lobby';
import { Layout, BookOpen, BarChart3, MessageSquare, Shield, ArrowLeft, Archive, LogOut, Loader2 } from 'lucide-react';

export default function App() {
  const [currentUser, setCurrentUser] = useState<AppUser | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);

  // Room State
  const [currentRoom, setCurrentRoom] = useState<Room | null>(null);
  const [roomRole, setRoomRole] = useState<'admin' | 'member'>('member');

  // Content State
  const [activeReadings, setActiveReadings] = useState<WeeklyReading[]>([]);
  const [loadingReadings, setLoadingReadings] = useState(false);

  const [reflections, setReflections] = useState<Reflection[]>([]);
  const [myReflections, setMyReflections] = useState<Record<string, Reflection>>({});

  const [view, setView] = useState<AppView>(AppView.HOME);

  // 1. Official Supabase Auth Handling
  useEffect(() => {
    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        fetchProfile(session.user.id);
      } else {
        setSessionLoading(false);
      }
    });

    // Listen for changes (Sign In, Sign Out, Recovery)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session) {
        fetchProfile(session.user.id);
      } else if (event === 'SIGNED_OUT') {
        setCurrentUser(null);
        setCurrentRoom(null);
        setSessionLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    setSessionLoading(true);
    const { data, error } = await supabase
      .from('app_users')
      .select('*')
      .eq('id', userId)
      .single();

    if (data && !error) {
      setCurrentUser(data as AppUser);
    } else {
      console.warn("User authenticated but profile not found. If this is a new signup, email verification might be required or the DB trigger might be missing.");
    }
    setSessionLoading(false);
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setCurrentRoom(null);
    setMyReflections({});
    setReflections([]);
    setActiveReadings([]);
    setView(AppView.HOME);
  };

  const exitRoom = () => {
    setCurrentRoom(null);
    setActiveReadings([]);
    setReflections([]);
    setMyReflections({});
    setView(AppView.HOME);
  };

  const enterRoom = (room: Room, role: 'admin' | 'member') => {
    setCurrentRoom(room);
    setRoomRole(role);
    setView(AppView.HOME);
  };

  // 2. Fetch Weekly Reading & Reflections (Scoped to Room)
  useEffect(() => {
    if (currentUser && currentRoom) {
      loadWeeklyData();
    }
  }, [currentUser, currentRoom]);

  const loadWeeklyData = async () => {
    if (!currentRoom) return;
    setLoadingReadings(true);

    const { data: allReadings, error } = await supabase
      .from('weekly_readings')
      .select('*')
      .eq('room_id', currentRoom.id)
      .order('created_at', { ascending: false });

    if (error) {
        console.error("Error loading readings:", error);
        setLoadingReadings(false);
        return;
    }

    if (!allReadings || allReadings.length === 0) {
        setActiveReadings([]);
        setLoadingReadings(false);
        return;
    }

    const explicitlyActive = allReadings.filter((r: WeeklyReading) => r.is_active === true);
    let currentActive: WeeklyReading[] = explicitlyActive.length > 0 ? explicitlyActive : [allReadings[0]];

    setActiveReadings(currentActive);

    const normalize = (s: string) => s.replace(/[\s\u00A0]+/g, '').toLowerCase();
    const activeReferences = new Set(currentActive.map(r => normalize(r.reference)));
    const relatedReadingIds = allReadings
        .filter((r: WeeklyReading) => activeReferences.has(normalize(r.reference)))
        .map((r: WeeklyReading) => r.id);

    fetchReflections(relatedReadingIds);
  };

  const fetchReflections = async (readingIds: string[]) => {
    if (readingIds.length === 0) {
        setLoadingReadings(false);
        return;
    }

    const { data, error } = await supabase
      .from('reflections')
      .select(`*, app_users (username)`)
      .in('reading_id', readingIds);

    if (data && !error) {
        const formatted: Reflection[] = data.map((r: any) => {
            const userObj = Array.isArray(r.app_users) ? r.app_users[0] : r.app_users;
            return {
                id: r.id,
                user_id: r.user_id,
                reading_id: r.reading_id,
                user_name: userObj?.username || 'Unknown',
                timestamp: new Date(r.created_at).getTime(),
                text: r.text,
                acknowledged: r.acknowledged
            };
        });

        setReflections(formatted);

        if (currentUser) {
            const mine: Record<string, Reflection> = {};
            formatted.filter(r => r.user_id === currentUser.id).forEach(r => {
                mine[r.reading_id] = r;
            });
            setMyReflections(mine);
        }
    }
    setLoadingReadings(false);
  };

  const handleClockIn = async (readingId: string) => {
    if (!currentUser) return;
    const { data, error } = await supabase.from('reflections').insert({
        user_id: currentUser.id,
        reading_id: readingId,
        acknowledged: true,
        text: ''
    }).select().single();
    if (data && !error) loadWeeklyData();
  };

  const handleReflectionSubmit = async (text: string, readingId: string) => {
    const existing = myReflections[readingId];
    if (!existing) return;
    const { error } = await supabase.from('reflections').update({ text: text }).eq('id', existing.id);
    if (!error) {
        loadWeeklyData();
        setView(AppView.REFLECTIONS);
    }
  };

  if (sessionLoading) {
    return (
      <div className="min-h-screen bg-bible-50 flex items-center justify-center">
        <Loader2 size={40} className="animate-spin text-bible-500" />
      </div>
    );
  }

  if (!currentUser) {
    return <Auth onLogin={fetchProfile} />;
  }

  if (!currentRoom) {
    return <Lobby user={currentUser} onSelectRoom={enterRoom} onLogout={handleSignOut} />;
  }

  return (
    <div className="min-h-screen bg-bible-50 text-gray-800 font-sans pb-24 md:pb-20">
      <nav className="sticky top-0 z-50 bg-white/90 backdrop-blur-md border-b border-bible-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-3 overflow-hidden flex-1 md:flex-none">
              <button onClick={exitRoom} className="text-gray-500 hover:text-bible-800 transition-colors p-2 rounded-full hover:bg-bible-50 flex-shrink-0">
                <ArrowLeft size={20} />
              </button>
              <div className="flex items-center gap-2 cursor-pointer overflow-hidden" onClick={() => setView(AppView.HOME)}>
                <div className="bg-bible-600 p-1.5 rounded-lg text-white flex-shrink-0"><Layout size={18} /></div>
                <div className="min-w-0">
                  <span className="font-serif text-lg md:text-xl font-semibold text-bible-900 tracking-tight block leading-none truncate">{currentRoom.name}</span>
                  <span className="text-xs text-gray-500 bg-gray-100 px-1.5 py-0.5 rounded mt-0.5 inline-block font-mono">{currentRoom.code}</span>
                </div>
              </div>
            </div>

            <div className="hidden md:flex items-center space-x-1 sm:space-x-2">
              <NavButton active={view === AppView.HOME} onClick={() => setView(AppView.HOME)} icon={<BookOpen size={18}/>} label="Read" />
              <NavButton active={view === AppView.REFLECTIONS} onClick={() => setView(AppView.REFLECTIONS)} icon={<MessageSquare size={18}/>} label="Reflect" />
              <NavButton active={view === AppView.HISTORY} onClick={() => setView(AppView.HISTORY)} icon={<Archive size={18}/>} label="Archive" />
              <NavButton active={view === AppView.DASHBOARD} onClick={() => setView(AppView.DASHBOARD)} icon={<BarChart3 size={18}/>} label="Review" />
              {roomRole === 'admin' && <NavButton active={view === AppView.ADMIN} onClick={() => setView(AppView.ADMIN)} icon={<Shield size={18}/>} label="Admin" />}
            </div>

            <div className="flex items-center pl-2">
                 <button onClick={handleSignOut} title="Sign Out" className="text-gray-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50">
                    <LogOut size={20} />
                 </button>
            </div>
          </div>
        </div>
      </nav>

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-2 flex justify-around z-50 pb-safe shadow-[0_-2px_10px_rgba(0,0,0,0.05)]">
        <MobileNavButton active={view === AppView.HOME} onClick={() => setView(AppView.HOME)} icon={<BookOpen size={20}/>} label="Read" />
        <MobileNavButton active={view === AppView.REFLECTIONS} onClick={() => setView(AppView.REFLECTIONS)} icon={<MessageSquare size={20}/>} label="Reflect" />
        <MobileNavButton active={view === AppView.HISTORY} onClick={() => setView(AppView.HISTORY)} icon={<Archive size={20}/>} label="Archive" />
        <MobileNavButton active={view === AppView.DASHBOARD} onClick={() => setView(AppView.DASHBOARD)} icon={<BarChart3 size={20}/>} label="Review" />
        {roomRole === 'admin' && <MobileNavButton active={view === AppView.ADMIN} onClick={() => setView(AppView.ADMIN)} icon={<Shield size={20}/>} label="Admin" />}
      </div>

      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {view === AppView.HOME && (
          <div className="space-y-12 animate-fade-in-up">
            {loadingReadings ? (
               <div className="w-full h-64 bg-bible-100 animate-pulse rounded-xl"></div>
            ) : activeReadings.length > 0 ? (
               activeReadings.map(reading => (
                 <div key={reading.id} className="space-y-6">
                    <VerseHero verse={reading} loading={false} hasAcknowledged={!!myReflections[reading.id]} onAcknowledge={() => handleClockIn(reading.id)} />
                    {myReflections[reading.id] && (
                        <div className="max-w-3xl mx-auto">
                            <ReflectionInput onSubmit={(text) => handleReflectionSubmit(text, reading.id)} />
                        </div>
                    )}
                 </div>
               ))
            ) : (
                <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-200">
                    <h2 className="text-xl font-serif text-gray-500 mb-2">No active scriptures.</h2>
                    <p className="text-gray-400">Wait for the Room Admin to publish a verse.</p>
                    {roomRole === 'admin' && (
                        <button onClick={() => setView(AppView.ADMIN)} className="mt-4 text-bible-600 font-medium underline hover:text-bible-800">Go to Admin Panel to set one.</button>
                    )}
                </div>
            )}
          </div>
        )}

        {view === AppView.REFLECTIONS && <ReflectionsList reflections={reflections} currentUser={currentUser} isAdmin={roomRole === 'admin'} onUpdateReflection={loadWeeklyData} readingDate={activeReadings[0]?.created_at} reference={activeReadings[0]?.reference} theme={activeReadings[0]?.theme} />}
        {view === AppView.HISTORY && currentRoom && <History room={currentRoom} isAdmin={roomRole === 'admin'} activeReadings={activeReadings} />}
        {view === AppView.DASHBOARD && activeReadings.length > 0 && <Dashboard reflections={reflections.filter(r => r.reading_id === activeReadings[0].id)} verse={activeReadings[0]} />}
        {view === AppView.ADMIN && roomRole === 'admin' && currentRoom && <AdminPanel room={currentRoom} currentUser={currentUser} currentReading={activeReadings[0] || null} activeReadings={activeReadings} onReadingUpdate={loadWeeklyData} onRoomUpdate={(updated) => setCurrentRoom(updated)} />}
      </main>
    </div>
  );
}

const NavButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button onClick={onClick} className={`px-3 sm:px-4 py-2 rounded-full text-sm font-medium transition-all flex items-center gap-2 ${active ? 'bg-bible-100 text-bible-800' : 'text-gray-500 hover:text-bible-600 hover:bg-white'}`}>
    {icon}
    <span className="hidden md:inline">{label}</span>
  </button>
);

const MobileNavButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
    <button onClick={onClick} className={`flex flex-col items-center justify-center p-2 rounded-lg w-full transition-all ${active ? 'text-bible-800 bg-bible-50' : 'text-gray-400 hover:text-gray-600'}`}>
      {icon}
      <span className="text-[10px] font-medium mt-1 uppercase tracking-wide">{label}</span>
    </button>
  );

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { AppUser } from '../types';
import { User, Lock, Mail, Loader2, AlertCircle, ArrowLeft, CheckCircle } from 'lucide-react';

interface AuthProps {
  onLogin: (userId: string) => void;
}

type AuthMode = 'signin' | 'signup' | 'forgot' | 'reset';

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<AuthMode>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // Check if we arrived here via a password reset link
  useEffect(() => {
    if (window.location.hash.includes('type=recovery')) {
      setMode('reset');
    }
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    const normalizedEmail = email.toLowerCase().trim();

    try {
      if (mode === 'signup') {
        const { data, error } = await supabase.auth.signUp({
          email: normalizedEmail,
          password,
          options: {
            data: { username },
            // Redirect back to this app after verification
            emailRedirectTo: window.location.origin,
          }
        });

        if (error) throw error;
        if (data.user && data.session) {
           // User signed up and email verification is disabled (direct login)
           onLogin(data.user.id);
        } else {
           // User signed up and email verification is enabled
           setMessage({ type: 'success', text: "Verification email sent! Please check your inbox to activate your account." });
        }

      } else if (mode === 'signin') {
        const { data, error } = await supabase.auth.signInWithPassword({
          email: normalizedEmail,
          password,
        });

        if (error) throw error;
        if (data.user) onLogin(data.user.id);

      } else if (mode === 'forgot') {
        const { error } = await supabase.auth.resetPasswordForEmail(normalizedEmail, {
          redirectTo: `${window.location.origin}#mode=reset`,
        });
        if (error) throw error;
        setMessage({ type: 'success', text: "Recovery link sent! Check your email to reset your password." });

      } else if (mode === 'reset') {
        const { error } = await supabase.auth.updateUser({ password });
        if (error) throw error;
        setMessage({ type: 'success', text: "Password updated successfully! You can now sign in." });
        setTimeout(() => setMode('signin'), 2000);
      }
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || "An error occurred" });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-bible-50 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md border border-bible-100">
        <div className="text-center mb-8">
           <div className="inline-block mb-4">
             <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 2000 2000" className="w-24 h-24">
                <path fill="#99582a" d="M1360,448c51.28,0,99.5,19.97,135.76,56.24,36.26,36.26,56.24,84.48,56.24,135.76v720c0,51.29-19.97,99.5-56.24,135.76-36.26,36.26-84.48,56.24-135.76,56.24h-720c-51.28,0-99.5-19.97-135.76-56.24-36.26-36.26-56.24-84.48-56.24-135.76v-720c0-51.29,19.97-99.5,56.24-135.76,36.26-36.26,84.48-56.24,135.76-56.24h720M1360,400h-720c-132.55,0-240,107.45-240,240v720c0,132.55,107.45,240,240,240h720c132.55,0,240-107.45,240-240v-720c0-132.55-107.45-240-240-240h0Z"/>
                <path fill="#99582a" d="M1180,400h-540c-132.55,0-240,107.45-240,240v720c0,132.55,107.45,240,240,240h540c132.55,0,240-107.45,240-240v-720c0-132.55-107.45-240-240-240ZM1222,1066c-36.45,0-66-29.55-66-66s29.55-66,66-66,66,29.55,66,66-29.55,66-66,66Z"/>
             </svg>
           </div>
           <h1 className="font-serif text-4xl text-bible-900 mb-2 font-bold tracking-tight">Bible Room</h1>
           <p className="text-gray-500 text-lg">
             {mode === 'forgot' ? 'Reset your password' : 
              mode === 'reset' ? 'Set new password' : 
              'Your team\'s spiritual workspace.'}
           </p>
        </div>

        {message && (
          <div className={`mb-6 p-4 rounded-lg text-sm flex items-start gap-3 animate-fade-in-up ${message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
            {message.type === 'success' ? <CheckCircle className="mt-0.5" size={18} /> : <AlertCircle className="mt-0.5" size={18} />}
            <p>{message.text}</p>
          </div>
        )}

        {mode !== 'forgot' || !message || message.type !== 'success' ? (
          <form onSubmit={handleAuth} className="space-y-4">
            {(mode === 'signup') && (
              <div className="relative">
                <User className="absolute left-3 top-3 text-gray-500" size={20} />
                <input
                  type="text"
                  placeholder="Your Name"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-400 focus:border-transparent outline-none transition-all text-gray-900 bg-white placeholder:text-gray-400"
                  required
                />
              </div>
            )}

            {(mode !== 'reset') && (
              <div className="relative">
                <Mail className="absolute left-3 top-3 text-gray-500" size={20} />
                <input
                  type="email"
                  placeholder="Email address"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-400 focus:border-transparent outline-none transition-all text-gray-900 bg-white placeholder:text-gray-400"
                  required
                />
              </div>
            )}

            {(mode !== 'forgot') && (
              <div className="relative">
                <Lock className="absolute left-3 top-3 text-gray-500" size={20} />
                <input
                  type="password"
                  placeholder={mode === 'reset' ? "Enter new password" : "Password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-400 focus:border-transparent outline-none transition-all text-gray-900 bg-white placeholder:text-gray-400"
                  required
                  minLength={6}
                />
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-bible-800 hover:bg-bible-900 text-white font-medium py-3 rounded-lg transition-colors flex items-center justify-center gap-2 shadow-lg hover:shadow-xl transform active:scale-95"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : (
                mode === 'signin' ? 'Sign In' : 
                mode === 'signup' ? 'Create Account' : 
                mode === 'forgot' ? 'Send Recovery Email' : 'Update Password'
              )}
            </button>
          </form>
        ) : null}

        <div className="mt-6 text-center space-y-3">
          {mode === 'signin' && (
            <>
              <button
                onClick={() => { setMode('signup'); setMessage(null); }}
                className="block w-full text-bible-600 hover:text-bible-800 text-sm font-medium"
              >
                Need an account? Sign Up
              </button>
              <button
                onClick={() => { setMode('forgot'); setMessage(null); }}
                className="block w-full text-gray-400 hover:text-gray-600 text-sm"
              >
                Forgot your password?
              </button>
            </>
          )}

          {mode === 'signup' && (
            <button
              onClick={() => { setMode('signin'); setMessage(null); }}
              className="block w-full text-bible-600 hover:text-bible-800 text-sm font-medium"
            >
              Already have an account? Sign In
            </button>
          )}

          {(mode === 'forgot' || mode === 'reset') && (
            <button
              onClick={() => { setMode('signin'); setMessage(null); }}
              className="flex items-center justify-center gap-2 w-full text-gray-400 hover:text-bible-700 text-sm font-medium"
            >
              <ArrowLeft size={16} />
              Back to Sign In
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { AppUser } from '../types';
import { User, Lock, Mail, Loader2, AlertCircle, ArrowLeft, CheckCircle, Info } from 'lucide-react';

interface AuthProps {
  onLogin: (userId: string) => void;
}

type AuthMode = 'signin' | 'signup' | 'forgot' | 'reset';

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<AuthMode>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error' | 'info', text: string } | null>(null);

  // Check for recovery tokens in URL (password reset flow)
  useEffect(() => {
    // Supabase sends recovery links with #type=recovery or similar fragments
    const hash = window.location.hash;
    if (hash.includes('type=recovery') || hash.includes('access_token=')) {
      setMode('reset');
      setMessage({ type: 'info', text: 'You are now resetting your password. Please enter a new one below.' });
    }
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    const normalizedEmail = email.toLowerCase().trim();

    try {
      if (mode === 'signup') {
        const { data, error } = await supabase.auth.signUp({
          email: normalizedEmail,
          password,
          options: {
            data: { username: username || email.split('@')[0] },
            emailRedirectTo: window.location.origin,
          }
        });

        if (error) throw error;

        if (data.user && data.session) {
           onLogin(data.user.id);
        } else {
           setMessage({ 
             type: 'success', 
             text: "Verification email sent! Check your inbox to activate your official account. Note: If you were an existing user, signing up links your old data." 
           });
        }

      } else if (mode === 'signin') {
        const { data, error } = await supabase.auth.signInWithPassword({
          email: normalizedEmail,
          password,
        });

        if (error) {
          // Check for common migration error
          if (error.message.includes('Invalid login credentials')) {
             throw new Error("Invalid credentials. If you haven't used the new Login yet, please click 'Create Account' to migrate your old profile.");
          }
          throw error;
        }
        if (data.user) onLogin(data.user.id);

      } else if (mode === 'forgot') {
        const { error } = await supabase.auth.resetPasswordForEmail(normalizedEmail, {
          redirectTo: `${window.location.origin}/#mode=reset`,
        });
        if (error) throw error;
        setMessage({ type: 'success', text: "Recovery link sent! Check your email (and spam folder) to reset your password." });

      } else if (mode === 'reset') {
        const { error } = await supabase.auth.updateUser({ password });
        if (error) throw error;
        setMessage({ type: 'success', text: "Password updated! You can now sign in with your new password." });
        setTimeout(() => setMode('signin'), 2000);
      }
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || "An error occurred" });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-bible-50 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md border border-bible-100">
        <div className="text-center mb-8">
           <div className="inline-block mb-4">
             <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 2000 2000" className="w-24 h-24">
                <path fill="#99582a" d="M1360,448c51.28,0,99.5,19.97,135.76,56.24,36.26,36.26,56.24,84.48,56.24,135.76v720c0,51.29-19.97,99.5-56.24,135.76-36.26,36.26-84.48,56.24-135.76,56.24h-720c-51.28,0-99.5-19.97-135.76-56.24-36.26-36.26-56.24-84.48-56.24-135.76v-720c0-51.29,19.97-99.5,56.24-135.76,36.26-36.26,84.48-56.24,135.76-56.24h720M1360,400h-720c-132.55,0-240,107.45-240,240v720c0,132.55,107.45,240,240,240h720c132.55,0,240-107.45,240-240v-720c0-132.55-107.45-240-240-240h0Z"/>
                <path fill="#99582a" d="M1180,400h-540c-132.55,0-240,107.45-240,240v720c0,132.55,107.45,240,240,240h540c132.55,0,240-107.45,240-240v-720c0-132.55-107.45-240-240-240ZM1222,1066c-36.45,0-66-29.55-66-66s29.55-66,66-66,66,29.55,66,66-29.55,66-66,66Z"/>
             </svg>
           </div>
           <h1 className="font-serif text-4xl text-bible-900 mb-2 font-bold tracking-tight">Bible Room</h1>
           <p className="text-gray-500 text-lg">
             {mode === 'forgot' ? 'Reset your password' : 
              mode === 'reset' ? 'Set new password' : 
              'Your team\'s spiritual workspace.'}
           </p>
        </div>

        {/* Migration Alert for Old Users */}
        {mode === 'signin' && (
          <div className="mb-6 p-3 bg-bible-50 border border-bible-200 rounded-lg flex items-start gap-2 text-xs text-bible-800">
            <Info size={14} className="mt-0.5 flex-shrink-0" />
            <p><strong>Old User?</strong> Since we upgraded to Official Login, you must click <strong>"Create Account"</strong> once with your old email to activate your profile.</p>
          </div>
        )}

        {message && (
          <div className={`mb-6 p-4 rounded-lg text-sm flex items-start gap-3 animate-fade-in-up ${
            message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 
            message.type === 'info' ? 'bg-blue-50 text-blue-700 border border-blue-200' :
            'bg-red-50 text-red-700 border border-red-200'
          }`}>
            {message.type === 'success' ? <CheckCircle className="mt-0.5" size={18} /> : <AlertCircle className="mt-0.5" size={18} />}
            <p>{message.text}</p>
          </div>
        )}

        {(mode !== 'forgot' || !message || message.type !== 'success') ? (
          <form onSubmit={handleAuth} className="space-y-4">
            {(mode === 'signup') && (
              <div className="relative">
                <User className="absolute left-3 top-3 text-gray-500" size={20} />
                <input
                  type="text"
                  placeholder="Your Name"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-400 outline-none transition-all text-gray-900 bg-white placeholder:text-gray-400"
                  required
                />
