            )}

            {(mode !== 'reset') && (
              <div className="relative">
                <Mail className="absolute left-3 top-3 text-gray-500" size={20} />
                <input
                  type="email"
                  placeholder="Email address"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-400 outline-none transition-all text-gray-900 bg-white placeholder:text-gray-400"
                  required
                />
