                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-bible-400 outline-none transition-all text-gray-900 bg-white placeholder:text-gray-400"
