        ) : null}

        <div className="mt-6 text-center space-y-3">
          {mode === 'signin' && (
            <>
              <button
                onClick={() => { setMode('signup'); setMessage(null); }}
                className="block w-full text-bible-600 hover:text-bible-800 text-sm font-medium"
              >
                Need an account? Sign Up / Migrate
              </button>
              <button
                onClick={() => { setMode('forgot'); setMessage(null); }}
                className="block w-full text-gray-400 hover:text-gray-600 text-sm"
              >
                Forgot your password?
              </button>
            </>
          )}

          {mode === 'signup' && (
            <button
              onClick={() => { setMode('signin'); setMessage(null); }}
              className="block w-full text-bible-600 hover:text-bible-800 text-sm font-medium"
            >
              Already have an account? Sign In
            </button>
          )}

          {(mode === 'forgot' || mode === 'reset') && (
            <button
              onClick={() => { setMode('signin'); setMessage(null); }}
              className="flex items-center justify-center gap-2 w-full text-gray-400 hover:text-bible-700 text-sm font-medium"
            >
              <ArrowLeft size={16} />
              Back to Sign In
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { AppUser } from '../types';
import { User, Lock, Mail, Loader2, AlertCircle, ArrowLeft, CheckCircle, Info, ShieldCheck } from 'lucide-react';

interface AuthProps {
  onLogin: (userId: string) => void;
}

type AuthMode = 'signin' | 'signup' | 'forgot' | 'reset';

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<AuthMode>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error' | 'info', text: string } | null>(null);

  // 1. Detect Password Reset / Recovery from URL
  useEffect(() => {
    // Check if the URL contains the recovery type (from Supabase email link)
    const handleRecovery = async () => {
      const hash = window.location.hash;
      if (hash.includes('type=recovery') || hash.includes('access_token=')) {
        setMode('reset');
        setMessage({ 
          type: 'info', 
          text: 'Recovery link verified. Please set a new secure password (at least 8 characters with numbers).' 
        });
      }
    };

    handleRecovery();

    // Also listen for auth state changes specifically for recovery
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'PASSWORD_RECOVERY') {
        setMode('reset');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    const normalizedEmail = email.toLowerCase().trim();

    try {
      if (mode === 'signup') {
        const { data, error } = await supabase.auth.signUp({
          email: normalizedEmail,
          password,
          options: {
            data: { username: username || email.split('@')[0] },
            emailRedirectTo: window.location.origin,
          }
        });

        if (error) throw error;

        if (data.user && data.session) {
           onLogin(data.user.id);
        } else {
           setMessage({ 
             type: 'success', 
             text: "Verification email sent! Check your inbox (and spam) to activate your account. This will automatically link your old reflections." 
           });
        }

      } else if (mode === 'signin') {
        const { data, error } = await supabase.auth.signInWithPassword({
          email: normalizedEmail,
          password,
        });

        if (error) {
          if (error.message.includes('Invalid login credentials')) {
             throw new Error("Invalid credentials. If you were a user of the old app, please click 'Create Account' to migrate your data to the new secure system.");
          }
          throw error;
        }
        if (data.user) onLogin(data.user.id);

      } else if (mode === 'forgot') {
        const { error } = await supabase.auth.resetPasswordForEmail(normalizedEmail, {
          redirectTo: `${window.location.origin}/#mode=reset`,
        });
        if (error) throw error;
        setMessage({ type: 'success', text: "Recovery link sent! If the email doesn't arrive in 5 minutes, check your spam or verify your Site URL settings in Supabase." });

      } else if (mode === 'reset') {
        const { error } = await supabase.auth.updateUser({ password });
        if (error) throw error;
        setMessage({ type: 'success', text: "Password updated successfully! Redirecting to sign in..." });
        setTimeout(() => {
          setMode('signin');
          setPassword('');
        }, 3000);
      }
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || "An unexpected error occurred" });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-bible-50 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md border border-bible-100">
        <div className="text-center mb-8">
           <div className="inline-block mb-4">
             <div className="w-20 h-20 bg-bible-100 rounded-full flex items-center justify-center text-bible-700 mx-auto">
                <ShieldCheck size={40} />
             </div>
           </div>
           <h1 className="font-serif text-4xl text-bible-900 mb-2 font-bold tracking-tight">Bible Room</h1>
           <p className="text-gray-500 text-lg">
             {mode === 'forgot' ? 'Reset Password' : 
              mode === 'reset' ? 'Set New Password' : 
              'Secure Team Workspace'}
           </p>
        </div>

        {/* Migration Alert - Crucial for your existing users */}
        {mode === 'signin' && (
          <div className="mb-6 p-3 bg-blue-50 border border-blue-100 rounded-lg flex items-start gap-2 text-xs text-blue-800">
            <Info size={14} className="mt-0.5 flex-shrink-0" />
            <p><strong>Existing User?</strong> We've upgraded security. Please use <strong>Create Account</strong> with your old email one last time to sync your data.</p>
          </div>
        )}

        {message && (
          <div className={`mb-6 p-4 rounded-lg text-sm flex items-start gap-3 animate-fade-in-up ${
            message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 
            message.type === 'info' ? 'bg-bible-50 text-bible-800 border border-bible-200' :
            'bg-red-50 text-red-700 border border-red-200'
          }`}>
            {message.type === 'success' ? <CheckCircle className="mt-0.5" size={18} /> : <AlertCircle className="mt-0.5" size={18} />}
            <p>{message.text}</p>
          </div>
        )}

        {(mode !== 'forgot' || !message || message.type !== 'success') ? (
          <form onSubmit={handleAuth} className="space-y-4">
            {(mode === 'signup') && (
              <div className="relative">
                <User className="absolute left-3 top-3 text-gray-400" size={20} />
                <input
                  type="text"
                  placeholder="Full Name"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-bible-400 outline-none transition-all text-gray-900 bg-white"
                  required
                />
              </div>
            )}

            {(mode !== 'reset') && (
              <div className="relative">
                <Mail className="absolute left-3 top-3 text-gray-400" size={20} />
                <input
                  type="email"
                  placeholder="Email address"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-bible-400 outline-none transition-all text-gray-900 bg-white"
                  required
                />
              </div>
            )}

            {(mode !== 'forgot') && (
              <div className="space-y-1">
                <div className="relative">
                  <Lock className="absolute left-3 top-3 text-gray-400" size={20} />
                  <input
                    type="password"
                    placeholder={mode === 'reset' ? "New password (min 8 chars)" : "Password"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-bible-400 outline-none transition-all text-gray-900 bg-white"
                    required
                    minLength={8}
                  />
                </div>
                {(mode === 'signup' || mode === 'reset') && (
                  <p className="text-[10px] text-gray-400 px-1 italic">
                    Must be 8+ characters with at least one letter and one number.
                  </p>
                )}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-bible-800 hover:bg-bible-900 text-white font-medium py-3 rounded-lg transition-all flex items-center justify-center gap-2 shadow-lg active:scale-95 disabled:opacity-50"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : (
                mode === 'signin' ? 'Sign In' : 
                mode === 'signup' ? 'Create Secure Account' : 
                mode === 'forgot' ? 'Send Recovery Email' : 'Update Password'
              )}
            </button>
          </form>
        ) : null}

        <div className="mt-6 text-center space-y-4">
          {mode === 'signin' && (
            <>
              <button
                onClick={() => { setMode('signup'); setMessage(null); }}
                className="block w-full text-bible-700 hover:text-bible-900 text-sm font-semibold"
              >
                New here? Create Account / Migrate
              </button>
              <button
                onClick={() => { setMode('forgot'); setMessage(null); }}
                className="block w-full text-gray-400 hover:text-gray-600 text-xs"
              >
                Forgot your password?
              </button>
            </>
          )}

          {mode === 'signup' && (
            <button
              onClick={() => { setMode('signin'); setMessage(null); }}
              className="block w-full text-bible-700 hover:text-bible-900 text-sm font-semibold"
            >
              Already have an account? Sign In
            </button>
          )}

          {(mode === 'forgot' || mode === 'reset') && (
            <button
              onClick={() => { setMode('signin'); setMessage(null); setPassword(''); }}
              className="flex items-center justify-center gap-2 w-full text-gray-400 hover:text-bible-700 text-sm font-medium"
            >
              <ArrowLeft size={16} />
              Back to Sign In
            </button>
          )}
        </div>
      </div>
    </div>
  );
};
